// Build the GitHub Advisory Database queries for the lookback window.
const settings = $('Settings').first().json;
const since = $now.minus({ days: Number(settings.lookback_days) || 7 }).toISODate();
const base = 'https://api.github.com/advisories?per_page=100&sort=published&direction=desc&published=' + encodeURIComponent('>=' + since);
const queries = [{ kind: 'malware', url: base + '&type=malware' }];
if (settings.include_critical_vulnerabilities) queries.push({ kind: 'critical', url: base + '&type=reviewed&severity=critical' });
return queries.map((query) => ({ json: query }));

// Keep only what the matcher needs from each advisory (withdrawn advisories are ignored).
const advisories = new Map();
for (const { json: a } of $input.all()) {
  if (!a.ghsa_id || a.withdrawn_at) continue;
  const packages = (a.vulnerabilities || [])
    .filter((v) => v.package && v.package.name)
    .map((v) => ({
      ecosystem: String(v.package.ecosystem || '').toLowerCase(),
      name: v.package.name,
      range: v.vulnerable_version_range || '',
      fixed: typeof v.first_patched_version === 'string' ? v.first_patched_version : (v.first_patched_version?.identifier || ''),
    }));
  if (!packages.length) continue;
  advisories.set(a.ghsa_id, {
    ghsa_id: a.ghsa_id, cve_id: a.cve_id || '', type: a.type, severity: a.severity || 'unknown',
    summary: a.summary || '', html_url: a.html_url || `https://github.com/advisories/${a.ghsa_id}`,
    published_at: a.published_at, packages,
  });
}
return [{ json: { advisories: [...advisories.values()], count: advisories.size } }];

// Match every dependency of every repository against the recent advisories.
const ECOSYSTEM = { npm: 'npm', pypi: 'pip', gem: 'rubygems', maven: 'maven', nuget: 'nuget', golang: 'go', composer: 'composer', cargo: 'rust', githubactions: 'actions', pub: 'pub', swift: 'swift', hex: 'erlang' };
const normName = (ecosystem, name) => {
  const lower = String(name).toLowerCase();
  return ecosystem === 'pip' ? lower.replace(/[-_.]+/g, '-') : lower;
};
const parsePurl = (purl) => {
  const m = String(purl || '').match(/^pkg:([^/]+)\/([^@?#]+)@([^?#]+)/);
  if (!m) return null;
  const ecosystem = ECOSYSTEM[m[1].toLowerCase()];
  if (!ecosystem) return null;
  let name = decodeURIComponent(m[2]);
  if (ecosystem === 'maven') name = name.replace('/', ':');
  return { ecosystem, name, version: decodeURIComponent(m[3]) };
};
const parseVersion = (v) => {
  const clean = String(v).trim().replace(/^[vV=]+/, '').split('+')[0];
  const dash = clean.indexOf('-');
  const main = dash >= 0 ? clean.slice(0, dash) : clean;
  return { nums: main.split('.').map((x) => (/^\d+$/.test(x) ? Number(x) : x)), pre: dash >= 0 ? clean.slice(dash + 1) : '' };
};
const comparePart = (a, b) => (typeof a === 'number' && typeof b === 'number' ? a - b : String(a).localeCompare(String(b), undefined, { numeric: true }));
const compareVersions = (x, y) => {
  const a = parseVersion(x);
  const b = parseVersion(y);
  for (let i = 0; i < Math.max(a.nums.length, b.nums.length); i++) {
    const d = comparePart(a.nums[i] ?? 0, b.nums[i] ?? 0);
    if (d) return d < 0 ? -1 : 1;
  }
  if (a.pre === b.pre) return 0;
  if (!a.pre) return 1;
  if (!b.pre) return -1;
  return a.pre.localeCompare(b.pre, undefined, { numeric: true }) < 0 ? -1 : 1;
};
// GitHub advisory ranges look like "< 1.2.3", ">= 1.0, < 1.2.3" or "= 4.1.2"; every part must hold
const inRange = (version, range) => String(range || '').split(',').map((c) => c.trim()).filter(Boolean).every((c) => {
  const m = c.match(/^(>=|<=|>|<|=)?\s*(.+)$/);
  if (!m) return false;
  const d = compareVersions(version, m[2]);
  switch (m[1] || '=') {
    case '>=': return d >= 0;
    case '<=': return d <= 0;
    case '>': return d > 0;
    case '<': return d < 0;
    default: return d === 0;
  }
});
const affectsAllVersions = (range) => !String(range || '').trim() || /^>=?\s*0(\.0)*$/.test(String(range).trim());
const isExactVersion = (v) => /^[vV]?\d+(\.\d+)*([-+.][0-9A-Za-z.-]+)?$/.test(String(v || '').trim()) && !/(^|\.)[xX*](\.|$)/.test(String(v));
const { advisories } = $('Index Advisories').first().json;
const repos = $('Limit Repositories').all().map((r) => r.json);
const known = new Set($('Load Incidents').all().map((r) => r.json.key).filter(Boolean));

// Index affected packages by ecosystem and normalised name
const index = new Map();
for (const advisory of advisories) {
  for (const p of advisory.packages) {
    const k = `${p.ecosystem}|${normName(p.ecosystem, p.name)}`;
    if (!index.has(k)) index.set(k, []);
    index.get(k).push({ advisory, p });
  }
}

const groups = new Map();
const scanned = [];
const skipped = [];
$input.all().forEach((item, i) => {
  const repo = repos[item.pairedItem?.item ?? i];
  if (!repo || !repo.full_name) return;
  const packages = item.json?.sbom?.packages;
  if (!Array.isArray(packages)) { skipped.push(repo.full_name); return; }
  scanned.push(repo.full_name);
  for (const pkg of packages) {
    const purl = (pkg.externalRefs || []).find((r) => r.referenceType === 'purl')?.referenceLocator;
    const dep = parsePurl(purl);
    if (!dep) continue;
    for (const { advisory, p } of index.get(`${dep.ecosystem}|${normName(dep.ecosystem, dep.name)}`) || []) {
      const exact = isExactVersion(dep.version);
      const affected = exact ? inRange(dep.version, p.range) : affectsAllVersions(p.range);
      if (!affected) continue;
      const key = `${advisory.ghsa_id}|${repo.full_name}|${dep.ecosystem}:${dep.name}@${dep.version}`;
      if (known.has(key)) continue;
      if (!groups.has(advisory.ghsa_id)) groups.set(advisory.ghsa_id, { advisory, affected: new Map() });
      groups.get(advisory.ghsa_id).affected.set(key, {
        key, repo: repo.full_name, owner: repo.owner?.login || repo.full_name.split('/')[0], name: repo.name,
        visibility: repo.visibility || (repo.private ? 'private' : 'public'),
        ecosystem: dep.ecosystem, package: dep.name, version: dep.version, exact, fixed: p.fixed,
      });
    }
  }
});

return [...groups.values()].map((g) => ({
  json: { advisory: g.advisory, affected: [...g.affected.values()], scanned_repos: scanned.length, skipped_repos: skipped },
}));

