// Build the Slack alert from the advisory, the affected repositories and the AI response plan.
const group = $('Match Dependencies').item.json;
const plan = $json.output || {};
const a = group.advisory;
const esc = (value) => String(value ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const malware = a.type === 'malware';
const affectedLines = group.affected.slice(0, 15).map((x) =>
  `• *${esc(x.repo)}* (${x.visibility}): ${esc(x.package)}@${esc(x.version)}${x.exact ? '' : ' _(unconfirmed: version not pinned)_'}${x.fixed ? ` → fixed in ${esc(x.fixed)}` : ''}`);
if (group.affected.length > 15) affectedLines.push(`…and ${group.affected.length - 15} more`);
const text = [
  `${malware ? '🚨 *Compromised package in your repositories*' : '⚠️ *Critical vulnerability in your repositories*'}: <${a.html_url}|${esc(a.ghsa_id)}>${a.cve_id ? ` (${esc(a.cve_id)})` : ''}`,
  `*${esc(plan.headline || a.summary)}*`,
  '*Affected*', ...affectedLines,
  `*What happened:* ${esc(plan.what_happened)}`,
  '*Do now*', ...(plan.immediate_steps || []).slice(0, 6).map((s, i) => `${i + 1}. ${esc(s)}`),
  plan.how_to_fix ? `*Fix:* ${esc(plan.how_to_fix)}` : '',
  (plan.check_for_compromise || []).length ? '*Check whether you were compromised*' : '',
  ...(plan.check_for_compromise || []).slice(0, 5).map((s) => `• ${esc(s)}`),
].filter(Boolean).join('\n');
return { json: { ...group, plan, slack_text: text } };

// One Data Table row per affected repository and package version, so nothing is alerted twice.
const now = $now.toFormat('yyyy-MM-dd HH:mm');
return $input.all().flatMap(({ json: g }) => g.affected.map((x) => ({
  json: {
    key: x.key, ghsa_id: g.advisory.ghsa_id, advisory_type: g.advisory.type, severity: g.advisory.severity,
    repo: x.repo, ecosystem: x.ecosystem, package: x.package, version: x.version, fixed_version: x.fixed || '',
    confirmed: x.exact ? 'yes' : 'no', detected_at: now, status: 'open', summary: String(g.advisory.summary).slice(0, 500),
  },
})));

// Draft one GitHub issue per affected private repository and advisory (only when enabled).
if (!$('Settings').first().json.create_github_issues) return [];
// AI text is neutralised before it goes into Markdown: no HTML, no links or images, no @mentions
const safe = (value) => String(value ?? '').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/[\[\]]/g, '\\$&').replace(/@(?=\w)/g, '@\u200b');
const issues = [];
for (const { json: g } of $input.all()) {
  const a = g.advisory;
  const byRepo = {};
  for (const x of g.affected.filter((x) => x.visibility === 'private')) (byRepo[x.repo] ||= []).push(x);
  for (const [repo, list] of Object.entries(byRepo)) {
    const p = g.plan || {};
    issues.push({
      json: {
        owner: list[0].owner,
        name: list[0].name,
        title: `${a.type === 'malware' ? 'Compromised package' : 'Critical vulnerability'}: ${a.ghsa_id} affects ${list.map((x) => x.package).join(', ')}`.slice(0, 200),
        body: [
          `Opened by the Compromised Package Alarm n8n workflow on ${$now.toFormat('yyyy-MM-dd')}. Advisory: ${a.html_url}`,
          '| Package | Version | Fixed in | Confirmed |\n|---|---|---|---|\n' +
            list.map((x) => `| ${safe(x.package)} | ${safe(x.version)} | ${safe(x.fixed || 'none yet')} | ${x.exact ? 'yes' : 'no (version not pinned)'} |`).join('\n'),
          `**What happened:** ${safe(p.what_happened)}`,
          '**Do now:**\n' + (p.immediate_steps || []).map((s, i) => `${i + 1}. ${safe(s)}`).join('\n'),
          p.how_to_fix ? `**Fix:** ${safe(p.how_to_fix)}` : '',
          (p.check_for_compromise || []).length ? '**Check whether you were compromised:**\n' + p.check_for_compromise.map((s) => `- ${safe(s)}`).join('\n') : '',
        ].filter(Boolean).join('\n\n'),
      },
    });
  }
}
return issues;
